select setseed(0.937);
create table lecturas_plana (
  camion smallint not null,
  ts timestamptz not null,
  temp numeric(3,1) not null);
insert into lecturas_plana
select c, t, round((4 + 2 * sin(extract(epoch from t) / 3600.0 + c) + random())::numeric, 1)
from generate_series('2026-10-01 00:00+00'::timestamptz, '2026-10-30 23:59+00', interval '1 minute') t,
     generate_series(1, 30) c
order by t, c;
